import subprocess, binascii, hashlib
def cli(port, db, *args):
    return subprocess.run(["redis-cli","-p",str(port),"-n",str(db)]+list(args),capture_output=True,text=True).stdout.strip()
def dump_hash(port, db, k):
    out = subprocess.run(["redis-cli","--raw","-p",str(port),"-n",str(db),"dump",k],capture_output=True).stdout
    # DUMP payload = data + 2-byte CRC64 suffix; compare data only (TTL flags differ across versions)
    return hashlib.sha256(out[:-2]).hexdigest() if len(out)>2 else None
